window.ScripturaLexicons.BDAG_PART_0344 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-01\" data-source=\"BDAG\" data-search=\"συνεπιτίθημι verbo juntar-se a um ataque BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνεπιτίθημι</td><td>verbo</td><td>juntar-se a um ataque</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-02\" data-source=\"BDAG\" data-search=\"συνέπομαι verbo acompanhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνέπομαι</td><td>verbo</td><td>acompanhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-03\" data-source=\"BDAG\" data-search=\"συνεργέω verbo cooperar; ajudar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνεργέω</td><td>verbo</td><td>cooperar; ajudar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-04\" data-source=\"BDAG\" data-search=\"συνεργός, όν adjetivo substantivado auxiliar; colaborador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνεργός, όν</td><td>adjetivo substantivado</td><td>auxiliar; colaborador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-05\" data-source=\"BDAG\" data-search=\"συνέρχομαι verbo reunir-se; acompanhar; unir-se intimamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνέρχομαι</td><td>verbo</td><td>reunir-se; acompanhar; unir-se intimamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-06\" data-source=\"BDAG\" data-search=\"συνεσθίω verbo comer com BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνεσθίω</td><td>verbo</td><td>comer com</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-07\" data-source=\"BDAG\" data-search=\"σύνεσις, εως, ἡ substantivo feminino inteligência; entendimento; discernimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σύνεσις, εως, ἡ</td><td>substantivo feminino</td><td>inteligência; entendimento; discernimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-08\" data-source=\"BDAG\" data-search=\"συνεστώς particípio; remissão ver συνίστημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνεστώς</td><td>particípio; remissão</td><td>ver συνίστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-09\" data-source=\"BDAG\" data-search=\"συνετίζω verbo fazer compreender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνετίζω</td><td>verbo</td><td>fazer compreender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-10\" data-source=\"BDAG\" data-search=\"συνετός, ή, όν adjetivo inteligente; sagaz; sábio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνετός, ή, όν</td><td>adjetivo</td><td>inteligente; sagaz; sábio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-11\" data-source=\"BDAG\" data-search=\"συνευδοκέω verbo aprovar; consentir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνευδοκέω</td><td>verbo</td><td>aprovar; consentir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-12\" data-source=\"BDAG\" data-search=\"συνευρυθμίζω verbo pôr em harmonia com BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνευρυθμίζω</td><td>verbo</td><td>pôr em harmonia com</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-13\" data-source=\"BDAG\" data-search=\"συνευφραίνομαι verbo alegrar-se com BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνευφραίνομαι</td><td>verbo</td><td>alegrar-se com</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-14\" data-source=\"BDAG\" data-search=\"συνευωχέομαι verbo banquetear-se juntamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνευωχέομαι</td><td>verbo</td><td>banquetear-se juntamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-15\" data-source=\"BDAG\" data-search=\"συνέφαγον forma verbal; remissão ver συνεσθίω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνέφαγον</td><td>forma verbal; remissão</td><td>ver συνεσθίω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-16\" data-source=\"BDAG\" data-search=\"συνεφίστημι verbo participar de insurreição; atacar juntamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνεφίστημι</td><td>verbo</td><td>participar de insurreição; atacar juntamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-17\" data-source=\"BDAG\" data-search=\"συνέχω verbo sustentar; fechar; apertar; guardar; afligir; absorver; impelir; controlar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνέχω</td><td>verbo</td><td>sustentar; fechar; apertar; guardar; afligir; absorver; impelir; controlar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-18\" data-source=\"BDAG\" data-search=\"συνεχῶς advérbio continuamente; incessantemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνεχῶς</td><td>advérbio</td><td>continuamente; incessantemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-19\" data-source=\"BDAG\" data-search=\"συνζ- remissão ver συζ- BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνζ-</td><td>remissão</td><td>ver συζ-</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0344-20\" data-source=\"BDAG\" data-search=\"συνήγορος, ου, ὁ substantivo masculino defensor; advogado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνήγορος, ου, ὁ</td><td>substantivo masculino</td><td>defensor; advogado</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0344-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεπιτίθημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνεπιτίθημι</span> principalmente, como em sua única ocorrência em nossa literatura, médio <span class=\"greek\">συνεπιτίθεμαι</span>, 2.º aoristo (Dt 32:27) <span class=\"greek\">συνεπεθέμην</span> juntar-se a outros num ataque a pessoas ou coisas (Thu., Isaeus, X.; Polyb., Diod S, Plut.; LXX; Jos., Ant. 10, 116) absoluto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:9</a> (cf. Ps 3:7).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνέπομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνέπομαι</span> depoente médio; imperfeito <span class=\"greek\">συνειπόμην</span> (Hom.+; POxy 1415, 8; 2 e 3 Macc; Ath., R. 20 p. 73, 15) acompanhar <span class=\"greek\">τινί</span> alguém (Jos., Ant. 13, 21; TestJud 3:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:4</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεργέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνεργέω</span> imperfeito <span class=\"greek\">συνήργουν</span>; 1.º aoristo <span class=\"greek\">συνήργησα</span> (Eur., X.+; inscrições, papiros, LXX, Test12Patr, Philo; Jos., Bell. 6, 38, Ant. 1, 156; Just., D. 142, 2; Orig.) empenhar-se num esforço cooperativo, trabalhar juntamente com, auxiliar, ajudar, absoluto <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">συνεργοῦτος</span> (PAmh 152, 5 <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">συνεργήσαντος</span>; Did., Gen. 162, 10 <span class=\"greek\">συνεργῶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span> <span class=\"greek\">θεός</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:20</a>. <span class=\"greek\">παντί</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">συνεργοῦντι</span> a todo aquele que auxilia (pessoas como Estéfanas) no trabalho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:16</a>. Com <span class=\"greek\">συνεργοῦντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:1</a> pode-se suprir <span class=\"greek\">θεῷ</span> (Hofmann, Windisch, Sickenberger, NRSV) ou <span class=\"greek\">ὑμῖν</span> (Chrysost., Bengel, Schmiedel, Bachmann). <span class=\"greek\">ς</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">πράγματι</span> ser prestativo em todos os aspectos Hs 5, 6, 6. Com dativo da pessoa ou coisa auxiliada (X., Mem. 4, 3, 12; Diod S 4, 25, 4 <span class=\"greek\">ς</span>. <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐπιθυμίαις</span>=auxiliá-lo em seus desejos; OGI 45, 11 [III a.C.]; PSI 376, 4 [250 a.C.]; 1 Macc 12:1; TestReub 3:6; TestIss 3:7 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>): <span class=\"greek\">βλέπεις</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">συνήργει</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔργοις</span> <span class=\"greek\">αὐτοῦ</span> vês que a fé cooperava com (e assim auxiliava) suas boas obras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:22</a>. Com o objetivo indicado por <span class=\"greek\">εἰς</span> (Epict. 1, 9, 26; Appian, Syr. 59 §309 <span class=\"greek\">ἐς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θάνατον</span> <span class=\"greek\">ς</span>., Bell. Civ. 5, 90 §378; Philo, Agr. 13; TestGad 4:7 <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span>, <span class=\"greek\">εἰς</span> <span class=\"greek\">σωτηρίαν</span>): em <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀγαπῶσιν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">συνεργεῖ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀγαθόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:28</a>, <span class=\"greek\">ς</span>. significa auxiliar (ou trabalhar com) alguém para obter algo ou realizar algo (IG2, 654, 15f <span class=\"greek\">ς</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐλευθερίαν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πόλει</span>; Larfeld I 500; Plut., Mor. 769d <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">φύσις</span> <span class=\"greek\">γυναικὶ</span> … <span class=\"greek\">πρὸς</span> <span class=\"greek\">εὔνοιαν</span> <span class=\"greek\">ἀνδρὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φιλίαν</span> <span class=\"greek\">μεγάλα</span> <span class=\"greek\">συνήργησεν</span> ‘assim a natureza auxilia grandemente uma mulher com domínio de si a conquistar a benevolência e a amizade de seu marido’; cf. Polyb. 11, 9, 1). Então o sujeito será ou <span class=\"greek\">πάντα</span>, tudo auxilia (ou coopera com ou em favor de) aqueles que amam a Deus a obter o que é bom (Vulg., Zahn, Sickenberger, Althaus, RSV margem; NRSV), ou <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, que de fato é lido depois de <span class=\"greek\">συνεργεῖ</span> em bons e muito antigos manuscritos (P46 BA; Orig. Para <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">συνεργεῖν</span> acerca de deuses: X., Mem. 4, 3, 12; mas v. MBlack, The Interpr. of <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:28</a>: OCullmann Festschr. ’62, 166–72); neste último caso <span class=\"greek\">πάντα</span> é acusativo de especificação (<span class=\"greek\">πᾶς</span> 1d<span class=\"greek\">β</span>) em tudo Deus auxilia (ou trabalha em favor de ou com) aqueles que o amam a obter o que é bom (assim RSV; NRSV margem; siríaco, copta, BWeiss, RLipsius, Jülicher, Kühl, Ltzm.; Goodsp., Probs. 148–50.—Cf. OGI 219, 10f acerca de divindade auxiliadora. A expressão preposicional <span class=\"greek\">ς</span>. … <span class=\"greek\">εἰς</span> corresponderia exatamente a Alex. Aphr., Fat. 31 p. 203, 8 Br. segundo o códice H: <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Πύθιος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Λαί̈ῳ</span> <span class=\"greek\">συνεργεῖ</span>=‘em nenhum aspecto Apolo coopera com Laio para o bem’, ou ‘auxilia L. a obter o que é bom’. Para a ideia cf. Herm. Wr. 9, 4b <span class=\"greek\">πάντα</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">τοιούτῳ</span> [=<span class=\"greek\">θεοσεβεῖ</span>], <span class=\"greek\">κἂν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἄλλοις</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κακά</span>, <span class=\"greek\">ἀγαθά</span> <span class=\"greek\">ἐστι</span> ‘tudo é bom para tal pessoa [temente a Deus], ainda que seja mau para outros’; Plotin. 4, 3, 16, 21. JBauer, ZNW 50, ’59, 106–12. Cf. Sext. Emp., Outlines of Pyrrhonism I, 207 ‘ser vantajoso para alguém’ [comunicação de EKrentz]).—DELG s.v. <span class=\"greek\">ἔργον</span>. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεργός, όν</h1><div class=\"entry-meta\"><span>adjetivo substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνεργός</span>, <span class=\"greek\">όν</span> (Pind., Thu. et al.; inscrições, papiros; 2 Macc 8:7; Mel., P. 54, 396 [<span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">συνεργός</span>, com referência a <span class=\"greek\">ἁμαρτία</span>]) relativo a trabalhar juntamente com alguém, auxiliar, como substantivo, e sempre assim em nossa literatura, auxiliar, colaborador (Philo; Jos., Bell. 2, 102, Ant. 7, 346; Orig., C. Cels. 5, 58, 17; Polyb. 31, 24, 10). Paulo refere-se àqueles que o auxiliaram na propagação do evangelho como seus colaboradores (genitivo subjetivo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:3</a>, 9, 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:25</a>; 4:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:2</a> variante de leitura; Phlm 1; 24. Em lugar do genitivo pode haver indicação do campo em que se deu a cooperação <span class=\"greek\">εἰς</span> em (Alex. Aphr., An. Mant. p. 167, 9 Br.) <span class=\"greek\">συνεργοὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> colaboradores no Reino de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:11</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">συνεργός</span> colaborador entre vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:23</a>. <span class=\"greek\">συνεργὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">εὐαγγελίῳ</span> auxiliar de Deus no evangelho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:2</a>. <span class=\"greek\">συνεργοί</span> <span class=\"greek\">ἐσμεν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χαρᾶς</span> <span class=\"greek\">ὑμῶν</span> trabalhamos convosco para vos proporcionar alegria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:24</a> (sobre o genitivo cf. X., Cyr. 2, 4, 10; 3, 3, 10 <span class=\"greek\">συνεργοὺς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κοινοῦ</span> <span class=\"greek\">ἀγαθοῦ</span>). Com dativo daquilo que é auxiliado (Eur., Thu. et al.) <span class=\"greek\">ἵνα</span> <span class=\"greek\">συνεργοὶ</span> <span class=\"greek\">γινώμεθα</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀληθείᾳ</span> para que nos mostremos auxiliares da verdade 3J 8 (<span class=\"greek\">ς</span>. <span class=\"greek\">γίνεσθαί</span> <span class=\"greek\">τινι</span> como UPZ 146, 3 [II a.C.]). Em <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐσμεν</span> <span class=\"greek\">συνεργοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:9</a>, <span class=\"greek\">συν</span>- refere-se ou à comunhão com Deus somos colaboradores com Deus, ou à comunidade de mestres em Corinto somos colaboradores a serviço de Deus (assim VFurnish, JBL 80, ’61, 364–70).—New Docs 3, 154; DELG s.v. <span class=\"greek\">ἔργον</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνέρχομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνέρχομαι</span> (desde Il. 10, 224 [em tmese]; inscrições, papiros, LXX, pseudepígrafos, Philo, Joseph., Just.; Ath., R. 23, p. 77, 8) imperfeito <span class=\"greek\">συνηρχόμην</span>; futuro <span class=\"greek\">συνελεύσομαι</span>; 2.º aoristo <span class=\"greek\">συνῆλθον</span> (<span class=\"greek\">συνῆλθα</span> B-D-F §81, 3; W-S. §13, 13; Mlt-H. 208); particípio perfeito <span class=\"greek\">συνεληλυθώς</span>; mais-que-perfeito, 3.ª pessoa do plural <span class=\"greek\">συνεληλύθεισαν</span>, particípio feminino plural <span class=\"greek\">συνεληλυθεῖαι</span>.</p>\n<p class=\"entry-text\">① reunir-se com outros como grupo, congregar-se, juntar-se <span class=\"greek\">συνέρχεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄχλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:20</a>. <span class=\"greek\">συνέρχονται</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀρχιερεῖς</span> 14:53.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:6</a> (v. B-D-F §251; Rob. 695); 2:6, 37 D; 5:16; 10:27; 16:13; 19:32; 21:22 variante de leitura; 22:30; 28:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:26</a>. Com o acréscimo de <span class=\"greek\">εἰς</span> com acusativo de lugar (Pla., Leg. 6, 13, 767c; Diod S 13, 100, 7 <span class=\"greek\">συνῆλθον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἔφεσον</span>; Zech 8:21) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:16</a> variante de leitura; <span class=\"greek\">ἐν</span> com dativo de lugar (POxy 1187, 6) <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐκκλησίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:18</a>; <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:33</a> variante de leitura; <span class=\"greek\">ὅπου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:20</a>; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span> (v. <span class=\"greek\">αὐτός</span> 3b; <span class=\"greek\">ς</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span> Josh 9:2; Syntipas p. 75, 16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:20</a>; 14:23; B 4:10. Seguido de dativo, reunir-se com alguém, reunir-se na casa de alguém (PTebt 34, 4 [I a.C.] <span class=\"greek\">συνελθεῖν</span> <span class=\"greek\">Ὥρῳ</span>; Jos., Bell. 2, 411) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.53\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:53</a> variante de leitura; D 14:2. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> reunir-se para (encontrar) alguém (Ex 32:26) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:33</a> variante de leitura. Seguido de infinitivo de finalidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:15</a>; de <span class=\"greek\">εἰς</span> indicando finalidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:33</a>; IEph 13:1. <span class=\"greek\">εἰς</span> também pode introduzir um resultado não intencionado <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κρεῖσσον</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἧσσον</span> <span class=\"greek\">συνέρχεσθε</span> realizais vossas reuniões de tal modo que resultam não em vosso benefício, mas em vosso prejuízo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:17</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">κρίμα</span> v. 34 (sobre a solenidade de uma celebração cf. o escólio a Aristoph., Pax 967f: à pergunta ‘<span class=\"greek\">τίς</span> <span class=\"greek\">τῇδε</span>;’ [=“quem está aqui?”] o grupo responde ‘<span class=\"greek\">πολλοὶ</span> <span class=\"greek\">κἀγαθοί</span>’. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐποίουν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">σπένδοντες</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">συνειδότες</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">ἄτοπον</span> <span class=\"greek\">ἐκχωροῖεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σπονδῶν</span>=“muitos homens bons.” Ora, os que derramavam as libações costumavam fazer isso [formular a pergunta], para que aqueles que tinham consciência de algo impróprio em si mesmos pudessem ausentar-se da libação). Com indicação da natureza e da maneira da reunião <span class=\"greek\">συνέρχεσθε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μιᾷ</span> <span class=\"greek\">πίστει</span> IEph 20:2.</p>\n<p class=\"entry-text\">② vir/ir com uma ou mais pessoas, viajar juntamente com alguém (BGU 380, 13; 596, 4 [84 d.C.]) <span class=\"greek\">τινί</span> (EpArist 35; Jos., Ant. 9, 33) <span class=\"greek\">τοὺς</span> <span class=\"greek\">συνελθόντας</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">Ἰουδαίους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:33</a>. <span class=\"greek\">ἦσαν</span> <span class=\"greek\">συνεληλυθυῖαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Γαλιλαίας</span> <span class=\"greek\">αὐτῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:55</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:21</a>; 9:39; 10:23, 45; 11:12. <span class=\"greek\">ς</span>. <span class=\"greek\">τινι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> 15:38. <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> em lugar do dativo sozinho 21:16. <span class=\"greek\">συνελθόντων</span> <span class=\"greek\">ἐνθάδε</span> provavelmente significa (por causa de <span class=\"greek\">συνκαταβάντες</span> 25:5) voltaram aqui (comigo) 25:17.</p>\n<p class=\"entry-text\">③ unir-se numa relação íntima, juntar-se em contexto sexual (X., Mem. 2, 2, 4; Diod S 3, 58, 4; Ps.-Apollod. 1, 3, 3; Philo, Virt. 40; 111; Jos., Ant. 7, 168; 213) <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a> variante de leitura. Em <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">συνελθεῖν</span> <span class=\"greek\">αὐτούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:18</a> combinam-se relações domésticas e conjugais. (Nos contratos matrimoniais em papiros <span class=\"greek\">πρὸς</span> <span class=\"greek\">γάμον</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">συνελθεῖν</span> significa ‘casar-se’. Também sem <span class=\"greek\">πρὸς</span> <span class=\"greek\">γάμον</span>: BGU 970, 13 [II d.C.] <span class=\"greek\">συνηρχόμην</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">προγεγραμμένῳ</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἀνδρί</span>).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεσθίω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνεσθίω</span> imperfeito <span class=\"greek\">συνήσθιον</span>; 2.º aoristo <span class=\"greek\">συνέφαγον</span> (Pla. et al.; Plut., Lucian; SIG 1179; LXX; TestSim 6:7 [interpolação cristã]; JosAs 7:1) comer com <span class=\"greek\">τινί</span> alguém (Pla., Leg. 9, 881d; Epict., Ench. 36; Ps 100:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:11</a>; PEg2 34 (ASyn. 42, 30); com <span class=\"greek\">συμπίνειν</span> (como Polyaenus 6, 24; SIG 1179, 18f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:41</a>; ISm 3:3. Em lugar do dativo <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> (cf. Ex 18:12; Aristoph., Acharn. 277 <span class=\"greek\">ξυμπίνειν</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>; JosAs 7:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:12</a>. VParkin, Studia Evangelica III, ’64, 250–53; CHeil, Die Ablehnung der Speisegebote durch Paulus ’94.—DELG s.v. <span class=\"greek\">ἔδω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνεσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σύνεσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">συνίημι</span>; Hom. et al.)</p>\n<p class=\"entry-text\">① faculdade de compreensão, inteligência, agudeza, sagacidade (Pind. et al.; OGI 323, 6 [II a.C.] <span class=\"greek\">συνέσει</span> <span class=\"greek\">κ</span>. <span class=\"greek\">παιδείᾳ</span> <span class=\"greek\">προάγων</span>; LXX, pseudepígrafos, Philo; Jos., C. Ap. 2, 125; Ath. 1:3 e outras ocorrências; Orig., C. Cels. 4, 76, 6; Did., Gen. 226, 12)</p>\n<p class=\"entry-text\">ⓐ em geral <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:47</a> (v. Jos., Vi. 8f); D 12:4. <span class=\"greek\">ἡ</span> <span class=\"greek\">σύνεσις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">συνετῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:19</a> (Is 29:14). Com <span class=\"greek\">σοφία</span> (Aristot., EN 1, 13, 20; Diod S 9, 3, 3; Dt 4:6) 1 Cl 32:4. Todo o âmbito da vida interior é abrangido pela expressão <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὅλης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὅλης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">συνέσεως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὅλης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰσχύος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:33</a>.</p>\n<p class=\"entry-text\">ⓑ no âmbito religioso-ético (IG IV2/1, 86, 18; Iren. 1, 10, 3 [Harv. I 97, 11]) entendimento tal como Deus concede aos seus (LXX; pseudepígrafos; Just., D. 70, 5): com <span class=\"greek\">σοφία</span>, <span class=\"greek\">ἐπιστήμη</span>, <span class=\"greek\">γνῶσις</span> B 2:3; 21:5 (cf. Ex 31:3; 35:31; Sir 1:19). Com <span class=\"greek\">σοφία</span> (como Jos., Ant. 8, 24): <span class=\"greek\">σύνεσις</span> <span class=\"greek\">πνευματική</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:9</a>. Com <span class=\"greek\">ἐπίγνωσις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μυστηρίου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>: <span class=\"greek\">πλοῦτος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πληροφορίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">συνέσεως</span> 2:2. Com <span class=\"greek\">πίστις</span> AcPl Ha 8, 34= BMM verso, 7f [<span class=\"greek\">συν</span>]<span class=\"greek\">έσει</span>. Com <span class=\"greek\">φῶς</span> 1 Cl 16:12 (Is 53:11). Personificado com outras virtudes divinas (como nome gnóstico de um Éon Iren. 1, 1, 2 [Harv. I 11, 8]) Hs 9, 15, 2. Onde o Senhor habita há <span class=\"greek\">σύνεσις</span> <span class=\"greek\">πολλή</span> m 10, 1, 6.—<span class=\"greek\">σύνεσιν</span> <span class=\"greek\">αἰτεῖσθαι</span> IPol 1:3; Hs 5, 4, 3f. <span class=\"greek\">σύνεσιν</span> <span class=\"greek\">διδόναι</span> Hm 4, 2, 2a. <span class=\"greek\">ς</span>. <span class=\"greek\">λαμβάνειν</span> (Aristot., EN 1161b, 26) Hs 9, 2, 6. <span class=\"greek\">ς</span>. <span class=\"greek\">ἔχειν</span> (Hdt. 2, 5) 9, 22, 2b e 3; D 12:1 (v. Hdb., Suppl. 1 ad loc.; para interpretação diferente v. <span class=\"greek\">ἀριστερός</span>). <span class=\"greek\">ἀπέστη</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σύνεσις</span> o entendimento afastou-se deles Hs 9, 22, 2a. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">συνέσει</span> no entendimento correto (concedido por Deus, que compreende o verdadeiro significado) B 10:1. O arrependimento é <span class=\"greek\">σύν</span>. Hm 4, 2, 2b, c, d.</p>\n<p class=\"entry-text\">ⓒ a sabedoria do Criador (Theoph. Ant. 2, 15 [p. 138, 13]) 1 Cl 33:3; Hv 1, 3, 4.</p>\n<p class=\"entry-text\">② o conteúdo do entendimento ou da compreensão, discernimento, entendimento <span class=\"greek\">σύνεσις</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> discernimento de, entendimento de algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:7</a>.—DELG s.v. <span class=\"greek\">ἵημι</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεστώς</h1><div class=\"entry-meta\"><span>particípio; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνεστώς</span> v. <span class=\"greek\">συνίστημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνετίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνετίζω</span> futuro <span class=\"greek\">συνετιῶ</span>; imperativo do 1.º aoristo <span class=\"greek\">συνέτισον</span>; infinitivo <span class=\"greek\">συνετίσαι</span> LXX (Rhet. Gr. I 584, 30; LXX; ApcMos 13) fazer compreender <span class=\"greek\">τινά</span> alguém (TestLevi 4:5; 9:8; Hesych.; Suda) Hm 4, 2, 1. Passivo, receber discernimento Dg 12:9.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνετός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνετός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">συνίημι</span>) relativo a ser capaz de compreender com discernimento, inteligente, sagaz, sábio, de bom senso (Theognis, Pind. et al.; LXX; EpArist 148; Philo, Joseph.; Just.—Advérbio <span class=\"greek\">συνετῶς</span> [LXX; Just., D. 114, 3]; superlativo <span class=\"greek\">συνετώτατα</span> [Just., D. 87, 3]) <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:7</a> (Just., D. 2, 6). <span class=\"greek\">συνετὸν</span> <span class=\"greek\">εἶναι</span> Hm 12, 1, 2; Hs 5, 5, 4; 9, 2, 6. Com <span class=\"greek\">μακρόθυμος</span> m 5, 1, 1. (<span class=\"greek\">οἱ</span>) <span class=\"greek\">συνετοί</span> (com <span class=\"greek\">σοφοί</span>; v. <span class=\"greek\">σοφός</span> 2a<span class=\"greek\">α</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:21</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">σύνεσις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">συνετῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:19</a> (Is 29:14.—Cf. Maximus Tyr. 16, 4c <span class=\"greek\">συνετὰ</span> <span class=\"greek\">συνετοῖς</span>). <span class=\"greek\">οἱ</span> <span class=\"greek\">συνετοὶ</span> <span class=\"greek\">ἑαυτοῖς</span> aqueles que são sábios aos próprios olhos (com <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">ἐπιστήμονες</span>) B 4:11 (cf. Is 5:21). <span class=\"greek\">οἱ</span> <span class=\"greek\">λεγόμενοι</span> <span class=\"greek\">ς</span>. IEph 18:1. Do Criador <span class=\"greek\">συνετὸς</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> entendido em algo (com <span class=\"greek\">σοφὸς</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>) 1 Cl 60:1.—DELG s.v. <span class=\"greek\">ἵημι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνευδοκέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνευδοκέω</span> 1.º aoristo <span class=\"greek\">συνηυδόκησα</span> (Polyb. 32, 6, 9; Diod S; SIG 712, 46; papiros; 1 e 2 Macc) participar da aprovação, concordar com, aprovar, consentir em, simpatizar com, com dativo de pessoa (BGU 834, 24 [II d.C.]) aprovar alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:32</a> (como TestAsh 6:2); 1 Cl 35:6. Com dativo de coisa, aprovar, dar aprovação a (BGU 1130, 3 [I a.C.]; POxy 504, 32; PGen 11, 3 e outras ocorrências; 1 Macc 1:57; 2 Macc 11:24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:1</a>; Dg 9:1. Absoluto (Polyb. 23, 4, 13; Diod S 4, 24, 1; 11, 57, 5; BGU 1129, 6; 2 Macc 11:35) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:20</a>. <span class=\"greek\">συνευδοκησάσης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐκκλησίας</span> <span class=\"greek\">πάσης</span> com o consentimento de toda a assembleia (igreja) 1 Cl 44:3. Seguido de infinitivo, estar disposto a fazer algo (PMich 202, 12 [105 d.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:12f</a>. Com dativo de pessoa, seguido de acusativo e infinitivo Hs 5, 2, 11. <span class=\"greek\">ταύτῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">γνώμῃ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δεσπότου</span> <span class=\"greek\">συνηυδόκησεν</span> <span class=\"greek\">αὐτῷ</span>, <span class=\"greek\">ἵνα</span> o filho do senhor concordou com ele nesta decisão, a saber, que 5, 2, 8 (sobre o texto, que pode estar corrompido, v. MDibelius, Hdb. ad loc.).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνευρυθμίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνευρυθμίζω</span> perfeito passivo, 3.ª pessoa do singular <span class=\"greek\">συνευρύθμισται</span> pôr em harmonia com <span class=\"greek\">συνευρύθμισται</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐντολαῖς</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">χορδαῖς</span> <span class=\"greek\">κιθάρα</span> ele está em harmonia com os mandamentos (divinos), como uma lira com suas cordas IPhld 1:2 (cf. <span class=\"greek\">συναρμόζω</span> 3).—DELG s.v. <span class=\"greek\">ῥυθμός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνευφραίνομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνευφραίνομαι</span> imperativo aoristo, 2.ª pessoa do singular <span class=\"greek\">συνευφράνθητι</span> (TestAbr A 4 p. 81, 24 [Stone p. 10]) alegrar-se (juntamente) com (Ps.-Dionys. Hal., A. Rh. 2, 5; Ael. Aristid. 42, 9 K.=6 p. 68 D.; Pollux 5, 129; Pr 5:18; TestAbr loc. cit.; Philo, Conf. Lingu. 6) seguido de dativo (Demosth. 18, 217; Herodian 2, 8, 9) B 2:3.—DELG s.v. <span class=\"greek\">φρήν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνευωχέομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνευωχέομαι</span> depoente passivo com sentido ativo, banquetear-se juntamente (Aristot., Eth. Eud. 7, 12, 14, 1245b; Posidonius: 87 Fgm. 15, 3 Jac. [em Athen. 4, 152b]; Philo, Spec. Leg. 4, 119 e outras ocorrências) Jd 12. <span class=\"greek\">τινί</span> com alguém (Lucian, Ver. Hist. 2, 15, Ep. Sat. 4, 36 e outras ocorrências; Jos., Ant. 1, 92; 4, 203; BGU 596, 10 [I d.C.] <span class=\"greek\">ὅπως</span> <span class=\"greek\">συνευωχηθῇς</span> <span class=\"greek\">ἡμῖν</span>; PGM 4, 3150) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:13</a>.—DELG s.v. <span class=\"greek\">εὐωχέω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνέφαγον</h1><div class=\"entry-meta\"><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνέφαγον</span> v. <span class=\"greek\">συνεσθίω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεφίστημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνεφίστημι</span> 2.º aoristo <span class=\"greek\">συνεπέστην</span> (Thu. et al.) intransitivo, participar de uma insurreição, juntar-se a um ataque <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> contra alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:22</a>.—DELG s.v. <span class=\"greek\">ἵστημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνέχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνέχω</span> futuro <span class=\"greek\">συνέξω</span>; 2.º aoristo <span class=\"greek\">συνέσχον</span>. Passivo: imperfeito <span class=\"greek\">συνειχόμην</span>; futuro, 3.ª pessoa do plural <span class=\"greek\">συσχεθήσονται</span> Job 36:8; En 21:10; aoristo <span class=\"greek\">συνεσχέθην</span> LXX, AcPl Ha (Hom.+).</p>\n<p class=\"entry-text\">① manter unido como uma unidade, manter unido, sustentar <span class=\"greek\">τὶ</span> algo (Ael. Aristid. 43, 16 K.=1 p. 6 D.: <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ς</span>.; PTebt 410, 11. Cf. IG XIV, 1018, a Átis <span class=\"greek\">συνέχοντι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πᾶν</span> [v. CWeyman, BZ 14, 1917, 17f]; PGM 13, 843. Outros exemplos em Cumont3 230, 57; Wsd 1:7; Aristobulus em Eus., PE 13, 12, 12 [=Holladay p. 184, 78; v. p. 229 n. 139 para referências e bibliografia adicionais]; Philo; Jos., C. Ap.2, 208) <span class=\"greek\">συνέχει</span> <span class=\"greek\">αὐτὴ</span> (isto é, <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχή</span>) <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> Dg 6:7. Passivo 1 Cl 20:5.</p>\n<p class=\"entry-text\">② fechar mantendo unido, tapar, fechar (<span class=\"greek\">στόμα</span> Ps 68:16; Is 52:15; PsSol 17:19 <span class=\"greek\">πηγαὶ</span> <span class=\"greek\">συνεσχέθησαν</span>. Os céus, de modo que não haja chuva Dt 11:17; 3 Km 8:35) <span class=\"greek\">συνέσχον</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">αὐτῶν</span> isto é, recusaram-se a ouvir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.57\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:57</a>.</p>\n<p class=\"entry-text\">③ comprimir por todos os lados, de modo a deixar pouco espaço para movimento, apertar, comprimir na multidão <span class=\"greek\">τινά</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:45</a>. De uma cidade (2 Macc 9:2) <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐχθροί</span> <span class=\"greek\">σου</span> <span class=\"greek\">συνέξουσίν</span> <span class=\"greek\">σε</span> <span class=\"greek\">πάντοθεν</span> 19:43.</p>\n<p class=\"entry-text\">④ manter sob custódia, guardar (Lucian, Tox. 39; PMagd 42, 7; PLille 7, 15 [III a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.63\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:63</a>.</p>\n<p class=\"entry-text\">⑤ causar aflição pela força das circunstâncias, acometer, atacar, afligir, atormentar <span class=\"greek\">τινά</span> alguém <span class=\"greek\">τὰ</span> <span class=\"greek\">συνέχοντά</span> <span class=\"greek\">με</span> aquilo que me aflige IRo 6:3. Principalmente no passivo (Aeschyl., Hdt. et al.), ser atormentado por, acometido de, afligido por <span class=\"greek\">τινί</span> algo, de enfermidade (Pla. et al.; ApcMos 5; Tat. 2, 1; 3; SIG 1169, 50 <span class=\"greek\">ἀγρυπνίαις</span> <span class=\"greek\">συνεχόμενος</span>; POxy 896, 34 <span class=\"greek\">πυραιτίοις</span> <span class=\"greek\">συνεχόμενος</span>) <span class=\"greek\">νόσοις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βασάνοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:24</a>; <span class=\"greek\">πυρετῷ</span> (Hippiatr. I 6, 23; Jos., Ant. 13, 398; v. também <span class=\"greek\">πυρετός</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:38</a>; <span class=\"greek\">πυρετοῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δυσεντερίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:8</a>. De estados emocionais desagradáveis (Diod S 29, 25 <span class=\"greek\">λύπῃ</span>; TestAbr A 16, p. 96, 21 [Stone p. 40] <span class=\"greek\">δειλίᾳ</span> <span class=\"greek\">πολλῇ</span>; Aelian, VH 14, 22 <span class=\"greek\">ὀδυρμῷ</span>; Ps.-Plut., De Fluv. 2, 1; 7, 5; 17, 3; 19, 1) <span class=\"greek\">φόβῳ</span> <span class=\"greek\">μεγάλῳ</span> <span class=\"greek\">συνείχοντο</span> foram dominados por grande medo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:37</a> (cf. Job 3:24). <span class=\"greek\">φόβῳ</span> <span class=\"greek\">μεγάλῳ</span> <span class=\"greek\">συσχεθεῖσα</span> AcPl Ha 3, 34; cf. 11, 16.—Sem o dativo (Leontios 16 p. 33, 13 <span class=\"greek\">συνεχόμενος</span>=atormentado) <span class=\"greek\">πῶς</span> <span class=\"greek\">συνέχομαι</span> quão grande é minha aflição, que angústia devo suportar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:50</a>. O apóstolo, dividido entre emoções conflitantes, diz <span class=\"greek\">συνέχομαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δύο</span> estou constrangido (a escolher) entre as duas coisas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:23</a>.</p>\n<p class=\"entry-text\">⑥ ocupar intensamente a atenção de alguém, <span class=\"greek\">συνέχομαί</span> <span class=\"greek\">τινι</span> estou ocupado com ou absorvido em algo (Herodian 1, 17, 9 <span class=\"greek\">ἡδοναῖς</span>; Diog. L. 7, 185 <span class=\"greek\">γέλωτι</span>; Wsd 17:19) <span class=\"greek\">συνείχετο</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> (Paulo) estava inteiramente absorvido na pregação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:5</a> (EHenschel, Theologia Viatorum 2, ’50, 213–15; cf. Arrian, Anab. 7, 21, 5 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷδε</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πόνῳ</span> <span class=\"greek\">ξυνείχοντο</span>=estavam intensamente empenhados nessa difícil tarefa), em contraste com a atividade citada no v. 3. Estreitamente relacionado está o sentido</p>\n<p class=\"entry-text\">⑦ dar impulso para alguma atividade, incitar, impelir, <span class=\"greek\">τινά</span> alguém <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">συνέχει</span> <span class=\"greek\">ἡμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:14</a> (assim Bachmann, Belser, Sickenberger, Lietzmann, Windisch, OHoltzmann, 20th Cent.; NRSV). Passivo <span class=\"greek\">συνείχετο</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Παῦλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:5</a> variante de leitura.</p>\n<p class=\"entry-text\">⑧ manter dentro de limites de modo a dirigir ou guiar, dirigir, controlar. Muitos, inclusive RSV e REB, oferecem esta interpretação para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:14</a> (v. 7 acima. Heinrici deixa em aberto a escolha entre 7 e 8. GHendry, ET 59, ’47/48, 82 propõe ‘incluir, abranger’.).—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεχῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνεχῶς</span> advérbio de <span class=\"greek\">συνεχής</span> (Just., D. 192, 1; Ath., R. 16 p. 68, 1), de tempo (Hes. et al.; inscrições, papiros; TestJob 2:3; Test12Patr; EpArist 78 e outras ocorrências; Philo; Jos., Vi. 20, Ant. 19, 318) continuamente, incessantemente <span class=\"greek\">ἐκζητεῖν</span> B 21:8.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνζ-</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνζ</span>- v. <span class=\"greek\">συζ</span>-.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0344-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνήγορος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνήγορος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aeschyl., Demosth. et al.; inscrições; PAmh 23, 15; 24 [II a.C.]; POxy 1479, 5; Philo, Conf. Lingu. 121; Ar. 8, 4; Tat.1, 2; empréstimo linguístico na literatura rabínica) aquele que atua como defensor em questões jurídicas, advogado (Diod S 1, 76, 1; Philo, Vi. Cont. 44) ISm 5:1.—DELG s.v. <span class=\"greek\">ἀγορά</span> 3.</p></section></article>"};
